mkdir -p /app
cat > /app/fastdom.c <<'CEOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <dlfcn.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 64
#define WORKLEN (8 * MAXN * MAXN + 256)

/* ILP64 LAPACK: 64-bit integer arguments.  gfortran-compiled OpenBLAS takes the
   two hidden character-length arguments at the end; pass them explicitly. */
typedef void (*dgeev_fn)(char *jobvl, char *jobvr, npy_intp *n, double *a,
                         npy_intp *lda, double *wr, double *wi, double *vl,
                         npy_intp *ldvl, double *vr, npy_intp *ldvr,
                         double *work, npy_intp *lwork, npy_intp *info,
                         size_t len1, size_t len2);

static dgeev_fn g_dgeev = NULL;
static double *g_buf = NULL;   /* one block: a | wr | wi | vr | work */
static double *g_a, *g_wr, *g_wi, *g_vr, *g_work;

static PyObject *
py_setup(PyObject *self, PyObject *args)
{
    const char *path;
    const char *sym;
    void *h, *f;

    if (!PyArg_ParseTuple(args, "ss", &path, &sym))
        return NULL;
    h = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (h == NULL) {
        PyErr_SetString(PyExc_ImportError, dlerror());
        return NULL;
    }
    f = dlsym(h, sym);
    if (f == NULL) {
        PyErr_Format(PyExc_ImportError, "symbol %s not found in %s", sym, path);
        return NULL;
    }
    g_dgeev = (dgeev_fn)f;
    if (g_buf == NULL) {
        size_t na = (size_t)MAXN * MAXN;
        g_buf = (double *)malloc(sizeof(double) * (na + 2 * MAXN + na + WORKLEN));
        if (g_buf == NULL)
            return PyErr_NoMemory();
        g_a = g_buf;
        g_wr = g_a + na;
        g_wi = g_wr + MAXN;
        g_vr = g_wi + MAXN;
        g_work = g_vr + na;
    }
    Py_RETURN_NONE;
}

static PyObject *
py_dom_eig(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr;
    npy_intp n, i, j, best, lda, ldvl, ldvr, lwork, info, nn;
    double bm, m, val[2];
    char jobvl = 'N', jobvr = 'V';
    const double *a;
    PyArray_Descr *dt;
    PyObject *ev, *vec;

    if (!PyArray_Check(arg) || PyArray_NDIM((PyArrayObject *)arg) != 2) {
        PyErr_SetString(PyExc_TypeError, "expected 2-D numpy array");
        return NULL;
    }
    arr = (PyArrayObject *)arg;
    n = PyArray_DIM(arr, 0);
    if (PyArray_DIM(arr, 1) != n || n < 1 || n > MAXN ||
        PyArray_TYPE(arr) != NPY_FLOAT64 ||
        !PyArray_IS_C_CONTIGUOUS(arr)) {
        PyErr_SetString(PyExc_TypeError, "unsupported array");
        return NULL;
    }
    a = (const double *)PyArray_DATA(arr);

    if (n == 1) {
        dt = PyArray_DescrFromType(NPY_FLOAT64);
        ev = PyArray_Scalar((void *)a, dt, NULL);
        Py_DECREF(dt);
        vec = PyArray_SimpleNew(1, &n, NPY_COMPLEX128);
        if (ev == NULL || vec == NULL) {
            Py_XDECREF(ev);
            Py_XDECREF(vec);
            return NULL;
        }
        memset(PyArray_DATA((PyArrayObject *)vec), 0, sizeof(double) * 2);
        *((double *)PyArray_DATA((PyArrayObject *)vec)) = 1.0;
        return Py_BuildValue("(NN)", ev, vec);
    }

    /* transpose into column-major workspace */
    for (i = 0; i < n; i++) {
        const double *row = a + i * n;
        for (j = 0; j < n; j++)
            g_a[j * n + i] = row[j];
    }

    nn = n; lda = n; ldvl = 1; ldvr = n; lwork = WORKLEN; info = 0;
    g_dgeev(&jobvl, &jobvr, &nn, g_a, &lda, g_wr, g_wi, NULL, &ldvl,
            g_vr, &ldvr, g_work, &lwork, &info, (size_t)1, (size_t)1);
    if (info != 0) {
        PyErr_Format(PyExc_RuntimeError, "dgeev failed, info=%ld", (long)info);
        return NULL;
    }

    best = 0;
    bm = -1.0;
    for (i = 0; i < n; i++) {
        m = hypot(g_wr[i], g_wi[i]);
        if (m > bm) { bm = m; best = i; }
    }

    val[0] = g_wr[best];
    val[1] = g_wi[best];
    dt = PyArray_DescrFromType(val[1] == 0.0 ? NPY_FLOAT64 : NPY_COMPLEX128);
    ev = PyArray_Scalar(val, dt, NULL);
    Py_DECREF(dt);

    vec = PyArray_SimpleNew(1, &n, NPY_COMPLEX128);
    if (ev == NULL || vec == NULL) {
        Py_XDECREF(ev);
        Py_XDECREF(vec);
        return NULL;
    }
    {
        double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
        if (val[1] == 0.0) {
            const double *col = g_vr + best * n;
            for (i = 0; i < n; i++) {
                out[2 * i] = col[i];
                out[2 * i + 1] = 0.0;
            }
        }
        else if (val[1] > 0.0) {
            const double *c0 = g_vr + best * n;
            const double *c1 = c0 + n;
            for (i = 0; i < n; i++) {
                out[2 * i] = c0[i];
                out[2 * i + 1] = c1[i];
            }
        }
        else {
            const double *c0 = g_vr + (best - 1) * n;
            const double *c1 = c0 + n;
            for (i = 0; i < n; i++) {
                out[2 * i] = c0[i];
                out[2 * i + 1] = -c1[i];
            }
        }
    }
    return Py_BuildValue("(NN)", ev, vec);
}

static PyMethodDef methods[] = {
    {"setup", py_setup, METH_VARARGS, "load LAPACK dgeev"},
    {"dom_eig", py_dom_eig, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moddef = {
    PyModuleDef_HEAD_INIT, "_fastdom", NULL, -1, methods
};

PyMODINIT_FUNC
PyInit__fastdom(void)
{
    PyObject *m = PyModule_Create(&moddef);
    if (m == NULL)
        return NULL;
    import_array();
    return m;
}
CEOF
echo "written"; wc -l /app/fastdom.c

cat > /app/eigen.py <<'PYEOF'
"""Dominant eigenpair of a small general real matrix.

Fast path: a small C extension (``_fastdom.so``) that calls LAPACK ``dgeev``
directly (skipping numpy's Python-level plumbing) and picks the eigenpair of
largest magnitude.  If anything about the input or the extension is unusual we
fall back to ``numpy.linalg.eig``.
"""

import glob
import os

import numpy as np


def _reference(A):
    eigenvalues, eigenvectors = np.linalg.eig(A)
    idx = int(np.argmax(np.abs(eigenvalues)))
    return eigenvalues[idx], eigenvectors[:, idx]


def _candidate_libraries():
    site = os.path.dirname(os.path.dirname(os.path.abspath(np.__file__)))
    pats = [
        os.path.join(site, "numpy.libs", "*openblas*"),
        os.path.join(site, "scipy.libs", "*openblas*"),
        os.path.join(site, "numpy", "..", "numpy.libs", "*openblas*"),
        os.path.join(site, "scipy", "linalg", "_flapack*"),
    ]
    seen = []
    for pat in pats:
        for path in sorted(glob.glob(pat)):
            if path not in seen:
                seen.append(path)
    try:
        import ctypes.util

        for name in ("lapack", "openblas", "blas"):
            path = ctypes.util.find_library(name)
            if path and path not in seen:
                seen.append(path)
    except Exception:
        pass
    return seen


def _load_fast():
    try:
        import importlib.util

        here = os.path.dirname(os.path.abspath(__file__))
        so = os.path.join(here, "_fastdom.so")
        if not os.path.exists(so):
            return None
        spec = importlib.util.spec_from_file_location("_fastdom", so)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        symbols = [
            "scipy_dgeev_64_",
            "dgeev_64_",
            "scipy_dgeev_",
            "dgeev_",
            "dgeev",
        ]
        for lib in _candidate_libraries():
            for sym in symbols:
                try:
                    mod.setup(lib, sym)
                except Exception:
                    continue
                return mod.dom_eig
    except Exception:
        pass
    return None


_fast = _load_fast()


def find_dominant_eigenvalue_and_eigenvector(A: np.ndarray):
    """
    Find the dominant eigenvalue and eigenvector of a general real square matrix.

    Args:
        A: Real-valued square matrix (accepts numpy arrays) up to size 10x10,
        dtype np.float64.

    Returns:
        eigenvalue: Dominant eigenvalue (numpy scalar, potentially complex)
        eigenvector: Corresponding eigenvector (np.ndarray, potentially complex)
    """
    if _fast is not None:
        try:
            return _fast(A)
        except Exception:
            pass
    return _reference(A)
PYEOF
cd /app && python3 eval.py

cat > /app/fastdom.c <<'CEOF'
/* _fastdom: dominant eigenpair of a small real (non-symmetric) matrix.
 *
 * Fast path : Hessenberg reduction + implicit-shift complex QR + inverse
 *             iteration, all in C.  Result is verified by a residual check.
 * Slow path : LAPACK dgeev, called through a runtime-resolved function pointer.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <dlfcn.h>
#include <complex.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 64
#define WORKLEN (8 * MAXN * MAXN + 256)

typedef double complex dcomplex;

/* ------------------------------------------------------------------ LAPACK */

/* ILP64 LAPACK: 64-bit integer arguments.  gfortran-compiled OpenBLAS takes the
   two hidden character-length arguments at the end; pass them explicitly. */
typedef void (*dgeev_fn)(char *jobvl, char *jobvr, npy_intp *n, double *a,
                         npy_intp *lda, double *wr, double *wi, double *vl,
                         npy_intp *ldvl, double *vr, npy_intp *ldvr,
                         double *work, npy_intp *lwork, npy_intp *info,
                         size_t len1, size_t len2);

static dgeev_fn g_dgeev = NULL;

static double *g_buf = NULL;          /* lapack workspace block */
static double *g_a, *g_wr, *g_wi, *g_vr, *g_work;

/* ------------------------------------------------------- own solver buffers */

static dcomplex *g_H;    /* Hessenberg form (reflectors kept in g_V) */
static dcomplex *g_Hq;   /* scratch copy for the QR iteration        */
static dcomplex *g_V;    /* Householder vectors                     */
static dcomplex *g_LU;   /* LU factors of H - lambda I              */
static dcomplex *g_x, *g_y;
static double *g_beta;
static npy_intp *g_piv;

static int
alloc_buffers(void)
{
    size_t nn = (size_t)MAXN * MAXN;
    if (g_buf == NULL) {
        g_buf = (double *)malloc(sizeof(double) * (nn + 2 * MAXN + nn + WORKLEN));
        if (g_buf == NULL)
            return -1;
        g_a = g_buf;
        g_wr = g_a + nn;
        g_wi = g_wr + MAXN;
        g_vr = g_wi + MAXN;
        g_work = g_vr + nn;
    }
    if (g_H == NULL) {
        g_H = (dcomplex *)malloc(sizeof(dcomplex) * nn);
        g_Hq = (dcomplex *)malloc(sizeof(dcomplex) * nn);
        g_V = (dcomplex *)malloc(sizeof(dcomplex) * nn);
        g_LU = (dcomplex *)malloc(sizeof(dcomplex) * nn);
        g_x = (dcomplex *)malloc(sizeof(dcomplex) * MAXN);
        g_y = (dcomplex *)malloc(sizeof(dcomplex) * MAXN);
        g_beta = (double *)malloc(sizeof(double) * MAXN);
        g_piv = (npy_intp *)malloc(sizeof(npy_intp) * MAXN);
        if (!g_H || !g_Hq || !g_V || !g_LU || !g_x || !g_y || !g_beta || !g_piv)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------ own eigensolver */

/* Householder reduction to upper Hessenberg form:  H = Q^H A Q.
   Reflectors are kept in V/beta (V[i*n+k], i>k is the vector for step k). */
static void
hess_reduce(dcomplex *H, npy_intp n, dcomplex *V, double *beta)
{
    npy_intp k, i, j;

    for (k = 0; k < n - 2; k++) {
        double nrm = 0.0, vn = 0.0, b;
        dcomplex x0, alpha, v0;

        for (i = k + 1; i < n; i++) {
            double re = creal(H[i * n + k]), im = cimag(H[i * n + k]);
            nrm += re * re + im * im;
        }
        nrm = sqrt(nrm);
        beta[k] = 0.0;
        if (nrm == 0.0)
            continue;
        x0 = H[(k + 1) * n + k];
        {
            double ax = cabs(x0);
            alpha = (ax == 0.0) ? (-nrm) : (-nrm * (x0 / ax));
        }
        v0 = x0 - alpha;
        V[(k + 1) * n + k] = v0;
        vn = creal(v0) * creal(v0) + cimag(v0) * cimag(v0);
        for (i = k + 2; i < n; i++) {
            dcomplex xi = H[i * n + k];
            V[i * n + k] = xi;
            vn += creal(xi) * creal(xi) + cimag(xi) * cimag(xi);
        }
        if (vn == 0.0)
            continue;
        b = 2.0 / vn;
        beta[k] = b;

        /* left:  H <- (I - b v v^H) H */
        for (j = k; j < n; j++) {
            dcomplex s = 0.0;
            for (i = k + 1; i < n; i++)
                s += conj(V[i * n + k]) * H[i * n + j];
            s *= b;
            for (i = k + 1; i < n; i++)
                H[i * n + j] -= s * V[i * n + k];
        }
        /* right: H <- H (I - b v v^H) */
        for (i = 0; i < n; i++) {
            dcomplex s = 0.0;
            for (j = k + 1; j < n; j++)
                s += H[i * n + j] * V[j * n + k];
            s *= b;
            for (j = k + 1; j < n; j++)
                H[i * n + j] -= s * conj(V[j * n + k]);
        }
    }
}

/* Implicit single-shift (Wilkinson) QR iteration on a complex upper Hessenberg
   matrix.  On return the diagonal holds the eigenvalues.  Returns 0 on
   success, -1 if it failed to converge. */
static int
qr_eigs(dcomplex *H, npy_intp n)
{
    const double eps = 2.220446049250313e-16;
    npy_intp nn = n - 1;
    long total = 0;

    while (nn >= 1) {
        int its = 0;
        npy_intp l;

        for (;;) {
            for (l = nn; l >= 1; l--) {
                double s = cabs(H[(l - 1) * n + l - 1]) + cabs(H[l * n + l]);
                if (s == 0.0)
                    s = 1.0;
                if (cabs(H[l * n + l - 1]) <= eps * s) {
                    H[l * n + l - 1] = 0.0;
                    break;
                }
            }
            if (l == nn)
                break;
            if (++its > 60 || ++total > 6000)
                return -1;
            {
                npy_intp m = nn;
                dcomplex dd = H[(m - 1) * n + m - 1];
                dcomplex e = H[(m - 1) * n + m];
                dcomplex f = H[m * n + m - 1];
                dcomplex g = H[m * n + m];
                dcomplex half = 0.5 * (dd + g);
                dcomplex disc = csqrt(half * half - (dd * g - e * f));
                dcomplex l1 = half + disc, l2 = half - disc;
                dcomplex mu = (cabs(l1 - g) <= cabs(l2 - g)) ? l1 : l2;
                dcomplex x = H[l * n + l] - mu;
                dcomplex y = H[(l + 1) * n + l];
                npy_intp k;

                for (k = l; k < nn; k++) {
                    double ax = cabs(x), ay = cabs(y), r = hypot(ax, ay), c;
                    dcomplex s, t1, t2;
                    npy_intp i, j, j0, i1;

                    if (r == 0.0) { c = 1.0; s = 0.0; }
                    else if (ax == 0.0) { c = 0.0; s = conj(y) / ay; }
                    else { c = ax / r; s = (x * conj(y)) / (ax * r); }

                    j0 = (k == l) ? l : k - 1;
                    for (j = j0; j <= nn; j++) {
                        t1 = H[k * n + j];
                        t2 = H[(k + 1) * n + j];
                        H[k * n + j] = c * t1 + s * t2;
                        H[(k + 1) * n + j] = -conj(s) * t1 + c * t2;
                    }
                    i1 = (k + 2 <= nn) ? k + 2 : nn;
                    for (i = 0; i <= i1; i++) {
                        t1 = H[i * n + k];
                        t2 = H[i * n + k + 1];
                        H[i * n + k] = c * t1 + conj(s) * t2;
                        H[i * n + k + 1] = -s * t1 + c * t2;
                    }
                    if (k + 1 < nn) {
                        x = H[(k + 1) * n + k];
                        y = H[(k + 2) * n + k];
                    }
                }
            }
        }
        nn--;
    }
    return 0;
}

/* Complex LU with partial pivoting. */
static void
lu_factor(dcomplex *M, npy_intp n, npy_intp *piv)
{
    npy_intp k, i, j;

    for (k = 0; k < n; k++) {
        npy_intp p = k;
        double best = cabs(M[k * n + k]);
        for (i = k + 1; i < n; i++) {
            double v = cabs(M[i * n + k]);
            if (v > best) { best = v; p = i; }
        }
        piv[k] = p;
        if (p != k) {
            for (j = 0; j < n; j++) {
                dcomplex t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        }
        {
            dcomplex pv = M[k * n + k];
            if (pv == 0.0)
                pv = 1e-300;
            for (i = k + 1; i < n; i++) {
                dcomplex m = M[i * n + k] / pv;
                M[i * n + k] = m;
                if (m != 0.0)
                    for (j = k + 1; j < n; j++)
                        M[i * n + j] -= m * M[k * n + j];
            }
        }
    }
}

static void
lu_solve(const dcomplex *M, npy_intp n, const npy_intp *piv,
         const dcomplex *b, dcomplex *x)
{
    npy_intp i, j;

    for (i = 0; i < n; i++)
        x[i] = b[i];
    for (i = 0; i < n; i++) {
        if (piv[i] != i) {
            dcomplex t = x[i];
            x[i] = x[piv[i]];
            x[piv[i]] = t;
        }
    }
    for (i = 1; i < n; i++) {
        dcomplex s = x[i];
        for (j = 0; j < i; j++)
            s -= M[i * n + j] * x[j];
        x[i] = s;
    }
    for (i = n - 1; i >= 0; i--) {
        dcomplex s = x[i];
        for (j = i + 1; j < n; j++)
            s -= M[i * n + j] * x[j];
        x[i] = s / M[i * n + i];
    }
}

/* Compute the eigenvector of the Hessenberg matrix H for eigenvalue lam by
   inverse iteration, then map it back through the Householder reflectors. */
static void
eigenvector(dcomplex *H, npy_intp n, dcomplex lam, dcomplex *V,
            const double *beta, dcomplex *x, dcomplex *y)
{
    npy_intp i, j, k;
    double scale = cabs(lam), nrm;
    double delta;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            scale += cabs(H[i * n + j]);
    delta = 1e-12 * scale;

    memcpy(g_LU, H, sizeof(dcomplex) * (size_t)(n * n));
    for (i = 0; i < n; i++)
        g_LU[i * n + i] -= lam + delta;
    lu_factor(g_LU, n, g_piv);

    for (i = 0; i < n; i++)
        x[i] = 1.0;
    lu_solve(g_LU, n, g_piv, x, y);
    nrm = 0.0;
    for (i = 0; i < n; i++) {
        double re = creal(y[i]), im = cimag(y[i]);
        nrm += re * re + im * im;
    }
    nrm = sqrt(nrm);
    if (nrm == 0.0 || !isfinite(nrm)) {
        for (i = 0; i < n; i++)
            x[i] = 1.0;
        return;
    }
    for (i = 0; i < n; i++)
        x[i] = y[i] / nrm;
    lu_solve(g_LU, n, g_piv, x, y);

    /* x <- Q y, i.e. apply P_1 ... P_{n-2} from the right-most first */
    for (k = n - 3; k >= 0; k--) {
        dcomplex s = 0.0;
        if (beta[k] == 0.0)
            continue;
        for (i = k + 1; i < n; i++)
            s += conj(V[i * n + k]) * y[i];
        s *= beta[k];
        for (i = k + 1; i < n; i++)
            y[i] -= s * V[i * n + k];
    }
    nrm = 0.0;
    for (i = 0; i < n; i++) {
        double re = creal(y[i]), im = cimag(y[i]);
        nrm += re * re + im * im;
    }
    nrm = sqrt(nrm);
    if (nrm == 0.0 || !isfinite(nrm)) {
        for (i = 0; i < n; i++)
            x[i] = 1.0;
        return;
    }
    for (i = 0; i < n; i++)
        x[i] = y[i] / nrm;
}

/* Relative residual  ||A x - lam x|| / (||A|| * ||x||). */
static double
residual(const double *a, npy_intp n, dcomplex lam, const dcomplex *x)
{
    double an = 0.0, rn = 0.0, xn = 0.0;
    npy_intp i, j;

    for (i = 0; i < n; i++) {
        dcomplex s = 0.0;
        for (j = 0; j < n; j++)
            s += a[i * n + j] * x[j];
        s -= lam * x[i];
        rn += creal(s) * creal(s) + cimag(s) * cimag(s);
        for (j = 0; j < n; j++)
            an += fabs(a[i * n + j]);
        xn += creal(x[i]) * creal(x[i]) + cimag(x[i]) * cimag(x[i]);
    }
    an += cabs(lam);
    if (xn == 0.0)
        return 1e300;
    return sqrt(rn) / (sqrt(xn) * (an > 1.0 ? an : 1.0));
}

/* Fast path.  Returns 0 on success, -1 if the caller should fall back. */
static int
fast_eig(const double *a, npy_intp n, dcomplex *lam_out, dcomplex *x_out)
{
    npy_intp i, j, best;
    double bestm;
    dcomplex lam;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g_H[i * n + j] = a[i * n + j];

    hess_reduce(g_H, n, g_V, g_beta);
    memcpy(g_Hq, g_H, sizeof(dcomplex) * (size_t)(n * n));
    if (qr_eigs(g_Hq, n) != 0)
        return -1;

    best = 0;
    bestm = -1.0;
    for (i = 0; i < n; i++) {
        double m = cabs(g_Hq[i * n + i]);
        if (m > bestm) { bestm = m; best = i; }
    }
    if (!isfinite(bestm))
        return -1;
    lam = g_Hq[best * n + best];

    eigenvector(g_H, n, lam, g_V, g_beta, g_x, g_y);
    if (residual(a, n, lam, g_x) > 1e-9)
        return -1;

    *lam_out = lam;
    for (i = 0; i < n; i++)
        x_out[i] = g_x[i];
    return 0;
}

