static PyObject *
py_setup(PyObject *self, PyObject *args)
{
    const char *path;
    const char *sym;
    void *h, *f;

    if (!PyArg_ParseTuple(args, "ss", &path, &sym))
        return NULL;
    if (alloc_buffers() != 0)
        return PyErr_NoMemory();
    h = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (h == NULL) {
        PyErr_SetString(PyExc_ImportError, dlerror());
        return NULL;
    }
    f = dlsym(h, sym);
    if (f == NULL) {
        PyErr_Format(PyExc_ImportError, "symbol %s not found in %s", sym, path);
        return NULL;
    }
    g_dgeev = (dgeev_fn)f;
    Py_RETURN_NONE;
}

/* LAPACK-based path (also used as fallback). */
static int
lapack_eig(const double *a, npy_intp n, double *wr, double *wi, double *vr)
{
    char jobvl = 'N', jobvr = 'V';
    npy_intp i, j, lda = n, ldvl = 1, ldvr = n, lwork = WORKLEN, info = 0, nn = n;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g_a[j * n + i] = a[i * n + j];
    g_dgeev(&jobvl, &jobvr, &nn, g_a, &lda, wr, wi, NULL, &ldvl, vr, &ldvr,
            g_work, &lwork, &info, (size_t)1, (size_t)1);
    return info == 0 ? 0 : -1;
}

static PyObject *
build_result(npy_intp n, dcomplex lam, const dcomplex *x, int have_x,
             const double *wr, const double *wi, const double *vr, npy_intp best)
{
    PyArray_Descr *dt;
    PyObject *ev, *vec;
    double val[2];
    npy_intp i;
    double *out;

    vec = PyArray_SimpleNew(1, &n, NPY_COMPLEX128);
    if (vec == NULL)
        return NULL;
    out = (double *)PyArray_DATA((PyArrayObject *)vec);

    if (have_x) {
        val[0] = creal(lam);
        val[1] = cimag(lam);
        for (i = 0; i < n; i++) {
            out[2 * i] = creal(x[i]);
            out[2 * i + 1] = cimag(x[i]);
        }
    }
    else {
        val[0] = wr[best];
        val[1] = wi[best];
        if (wi[best] == 0.0) {
            const double *col = vr + best * n;
            for (i = 0; i < n; i++) {
                out[2 * i] = col[i];
                out[2 * i + 1] = 0.0;
            }
        }
        else if (wi[best] > 0.0) {
            const double *c0 = vr + best * n, *c1 = c0 + n;
            for (i = 0; i < n; i++) {
                out[2 * i] = c0[i];
                out[2 * i + 1] = c1[i];
            }
        }
        else {
            const double *c0 = vr + (best - 1) * n, *c1 = c0 + n;
            for (i = 0; i < n; i++) {
                out[2 * i] = c0[i];
                out[2 * i + 1] = -c1[i];
            }
        }
    }

    dt = PyArray_DescrFromType(val[1] == 0.0 ? NPY_FLOAT64 : NPY_COMPLEX128);
    ev = PyArray_Scalar(val, dt, NULL);
    Py_DECREF(dt);
    if (ev == NULL) {
        Py_DECREF(vec);
        return NULL;
    }
    return Py_BuildValue("(NN)", ev, vec);
}

static int
check_array(PyObject *arg, npy_intp *np)
{
    PyArrayObject *arr;

    if (!PyArray_Check(arg) || PyArray_NDIM((PyArrayObject *)arg) != 2) {
        PyErr_SetString(PyExc_TypeError, "expected 2-D numpy array");
        return -1;
    }
    arr = (PyArrayObject *)arg;
    *np = PyArray_DIM(arr, 0);
    if (PyArray_DIM(arr, 1) != *np || *np < 1 || *np > MAXN ||
        PyArray_TYPE(arr) != NPY_FLOAT64 || !PyArray_IS_C_CONTIGUOUS(arr)) {
        PyErr_SetString(PyExc_TypeError, "unsupported array");
        return -1;
    }
    return 0;
}

static PyObject *
py_dom_eig(PyObject *self, PyObject *arg)
{
    npy_intp n, best;
    const double *a;
    dcomplex lam = 0.0, xv[MAXN];
    double bestm = -1.0;

    if (check_array(arg, &n) != 0)
        return NULL;
    a = (const double *)PyArray_DATA((PyArrayObject *)arg);

    if (fast_eig(a, n, &lam, xv) == 0)
        return build_result(n, lam, xv, 1, NULL, NULL, NULL, 0);

    /* fallback */
    if (g_dgeev == NULL) {
        PyErr_SetString(PyExc_RuntimeError, "no LAPACK available");
        return NULL;
    }
    if (lapack_eig(a, n, g_wr, g_wi, g_vr) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "dgeev failed");
        return NULL;
    }
    best = 0;
    for (npy_intp i = 0; i < n; i++) {
        double m = hypot(g_wr[i], g_wi[i]);
        if (m > bestm) { bestm = m; best = i; }
    }
    return build_result(n, 0.0, NULL, 0, g_wr, g_wi, g_vr, best);
}

/* LAPACK-only entry point (benchmarking / testing). */
static PyObject *
py_dom_eig_lapack(PyObject *self, PyObject *arg)
{
