cat > /app/fastdom.c <<'CEOF'
/* _fastdom: dominant eigenpair of a small real (possibly non-symmetric) matrix.
 *
 * Fast path : real Householder reduction to Hessenberg form, implicit-shift
 *             complex QR iteration for the eigenvalues, inverse iteration for
 *             the eigenvector.  The pair is verified with a residual check.
 * Slow path : LAPACK dgeev through a runtime-resolved function pointer, used
 *             whenever the fast path declines or is unavailable.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <dlfcn.h>
#include <complex.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 64
#define WORKLEN (8 * MAXN * MAXN + 256)

typedef double complex dcomplex;

/* ------------------------------------------------------------------ LAPACK */

/* ILP64 LAPACK: 64-bit integer arguments.  gfortran-compiled OpenBLAS takes the
   two hidden character-length arguments at the end; pass them explicitly. */
typedef void (*dgeev_fn)(char *jobvl, char *jobvr, npy_intp *n, double *a,
                         npy_intp *lda, double *wr, double *wi, double *vl,
                         npy_intp *ldvl, double *vr, npy_intp *ldvr,
                         double *work, npy_intp *lwork, npy_intp *info,
                         size_t len1, size_t len2);

static dgeev_fn g_dgeev = NULL;

static double *g_buf = NULL;          /* lapack workspace block */
static double *g_a, *g_wr, *g_wi, *g_vr, *g_work;

/* ------------------------------------------------------- own solver buffers */

static double *g_H;      /* real Hessenberg form                        */
static double *g_V;      /* Householder vectors (V[i*n+k], i > k)       */
static double *g_beta;
static dcomplex *g_Hq;   /* complex copy, destroyed by the QR iteration  */
static dcomplex *g_LU;   /* LU factors of H - lambda I                  */
static dcomplex *g_x, *g_y;
static npy_intp *g_piv;

static long g_nfast = 0, g_nfall = 0;

static int
alloc_buffers(void)
{
    size_t nn = (size_t)MAXN * MAXN;
    if (g_buf == NULL) {
        g_buf = (double *)malloc(sizeof(double) * (nn + 2 * MAXN + nn + WORKLEN));
        if (g_buf == NULL)
            return -1;
        g_a = g_buf;
        g_wr = g_a + nn;
        g_wi = g_wr + MAXN;
        g_vr = g_wi + MAXN;
        g_work = g_vr + nn;
    }
    if (g_H == NULL) {
        g_H = (double *)malloc(sizeof(double) * nn);
        g_V = (double *)malloc(sizeof(double) * nn);
        g_beta = (double *)malloc(sizeof(double) * MAXN);
        g_Hq = (dcomplex *)malloc(sizeof(dcomplex) * nn);
        g_LU = (dcomplex *)malloc(sizeof(dcomplex) * nn);
        g_x = (dcomplex *)malloc(sizeof(dcomplex) * MAXN);
        g_y = (dcomplex *)malloc(sizeof(dcomplex) * MAXN);
        g_piv = (npy_intp *)malloc(sizeof(npy_intp) * MAXN);
        if (!g_H || !g_V || !g_beta || !g_Hq || !g_LU || !g_x || !g_y || !g_piv)
            return -1;
    }
    return 0;
}

/* -------------------------------------------------------- own eigensolver */

/* Real Householder reduction to upper Hessenberg form: H = Q^T A Q.
   The reflector for step k is stored in V[i*n+k] (i = k+1..n-1) with
   scaling beta[k]. */
static void
hess_reduce(double *H, npy_intp n, double *V, double *beta)
{
    npy_intp k, i, j;

    for (k = 0; k < n - 2; k++) {
        double nrm = 0.0, vn, b, x0, alpha, v0;

        for (i = k + 1; i < n; i++)
            nrm += H[i * n + k] * H[i * n + k];
        nrm = sqrt(nrm);
        beta[k] = 0.0;
        if (nrm == 0.0)
            continue;
        x0 = H[(k + 1) * n + k];
        alpha = (x0 >= 0.0) ? -nrm : nrm;
        v0 = x0 - alpha;
        V[(k + 1) * n + k] = v0;
        vn = v0 * v0;
        for (i = k + 2; i < n; i++) {
            V[i * n + k] = H[i * n + k];
            vn += H[i * n + k] * H[i * n + k];
        }
        if (vn == 0.0)
            continue;
        b = 2.0 / vn;
        beta[k] = b;

        for (j = k; j < n; j++) {           /* H <- (I - b v v^T) H */
            double s = 0.0;
            for (i = k + 1; i < n; i++)
                s += V[i * n + k] * H[i * n + j];
            s *= b;
            for (i = k + 1; i < n; i++)
                H[i * n + j] -= s * V[i * n + k];
        }
        for (i = 0; i < n; i++) {           /* H <- H (I - b v v^T) */
            double s = 0.0;
            for (j = k + 1; j < n; j++)
                s += H[i * n + j] * V[j * n + k];
            s *= b;
            for (j = k + 1; j < n; j++)
                H[i * n + j] -= s * V[j * n + k];
        }
    }
}

/* Implicit single-shift (Wilkinson) QR iteration on a complex upper Hessenberg
   matrix; on return the diagonal holds the eigenvalues. */
static int
qr_eigs(dcomplex *H, npy_intp n)
{
    const double eps = 2.220446049250313e-16;
    npy_intp nn = n - 1;
    long total = 0;

    while (nn >= 1) {
        int its = 0;
        npy_intp l;

        for (;;) {
            for (l = nn; l >= 1; l--) {
                double ar = creal(H[(l - 1) * n + l - 1]);
                double ai = cimag(H[(l - 1) * n + l - 1]);
                double br = creal(H[l * n + l]), bi = cimag(H[l * n + l]);
                double cr = creal(H[l * n + l - 1]), ci = cimag(H[l * n + l - 1]);
                double s = sqrt(ar * ar + ai * ai) + sqrt(br * br + bi * bi);
                if (s == 0.0)
                    s = 1.0;
                if (sqrt(cr * cr + ci * ci) <= eps * s) {
                    H[l * n + l - 1] = 0.0;
                    break;
                }
            }
            if (l == nn)
                break;
            if (++its > 60 || ++total > 6000)
                return -1;
            {
                npy_intp m = nn;
                dcomplex dd = H[(m - 1) * n + m - 1];
                dcomplex e = H[(m - 1) * n + m];
                dcomplex f = H[m * n + m - 1];
                dcomplex g = H[m * n + m];
                dcomplex half = 0.5 * (dd + g);
                dcomplex disc = csqrt(half * half - (dd * g - e * f));
                dcomplex l1 = half + disc, l2 = half - disc;
                dcomplex mu = (cabs(l1 - g) <= cabs(l2 - g)) ? l1 : l2;
                dcomplex x = H[l * n + l] - mu;
                dcomplex y = H[(l + 1) * n + l];
                npy_intp k;

                for (k = l; k < nn; k++) {
                    double xr = creal(x), xi = cimag(x);
                    double yr = creal(y), yi = cimag(y);
                    double ax = sqrt(xr * xr + xi * xi);
                    double ay = sqrt(yr * yr + yi * yi);
                    double r = sqrt(ax * ax + ay * ay);
                    double c, sr, si;
                    npy_intp i, j, j0, i1;

                    if (r == 0.0) { c = 1.0; sr = 0.0; si = 0.0; }
                    else if (ax == 0.0) { c = 0.0; sr = yr / ay; si = -yi / ay; }
                    else {
                        double inv = 1.0 / (ax * r);
                        c = ax / r;
                        sr = (xr * yr + xi * yi) * inv;
                        si = (xi * yr - xr * yi) * inv;
                    }

                    j0 = (k == l) ? l : k - 1;
                    for (j = j0; j <= nn; j++) {
                        double t1r = creal(H[k * n + j]), t1i = cimag(H[k * n + j]);
                        double t2r = creal(H[(k + 1) * n + j]);
                        double t2i = cimag(H[(k + 1) * n + j]);
                        H[k * n + j] = (c * t1r + sr * t2r - si * t2i)
                                     + I * (c * t1i + sr * t2i + si * t2r);
                        H[(k + 1) * n + j] = (-sr * t1r - si * t1i + c * t2r)
                                     + I * (-sr * t1i + si * t1r + c * t2i);
                    }
                    i1 = (k + 2 <= nn) ? k + 2 : nn;
                    for (i = 0; i <= i1; i++) {
                        double t1r = creal(H[i * n + k]), t1i = cimag(H[i * n + k]);
                        double t2r = creal(H[i * n + k + 1]);
                        double t2i = cimag(H[i * n + k + 1]);
                        H[i * n + k] = (c * t1r + sr * t2r + si * t2i)
                                     + I * (c * t1i + sr * t2i - si * t2r);
                        H[i * n + k + 1] = (-sr * t1r + si * t1i + c * t2r)
                                     + I * (-sr * t1i - si * t1r + c * t2i);
                    }
                    if (k + 1 < nn) {
                        x = H[(k + 1) * n + k];
                        y = H[(k + 2) * n + k];
                    }
                }
            }
        }
        nn--;
    }
    return 0;
}

/* Complex LU with partial pivoting. */
static void
lu_factor(dcomplex *M, npy_intp n, npy_intp *piv)
{
    npy_intp k, i, j;

    for (k = 0; k < n; k++) {
        npy_intp p = k;
        double br = creal(M[k * n + k]), bi = cimag(M[k * n + k]);
        double best = br * br + bi * bi;
        for (i = k + 1; i < n; i++) {
            double ar = creal(M[i * n + k]), ai = cimag(M[i * n + k]);
            double v = ar * ar + ai * ai;
            if (v > best) { best = v; p = i; }
        }
        piv[k] = p;
        if (p != k) {
            for (j = 0; j < n; j++) {
                dcomplex t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        }
        {
            dcomplex pv = M[k * n + k];
            if (pv == 0.0)
                pv = 1e-300;
            for (i = k + 1; i < n; i++) {
                dcomplex m = M[i * n + k] / pv;
                M[i * n + k] = m;
                if (m != 0.0)
                    for (j = k + 1; j < n; j++)
                        M[i * n + j] -= m * M[k * n + j];
            }
        }
    }
}

static void
lu_solve(const dcomplex *M, npy_intp n, const npy_intp *piv,
         const dcomplex *b, dcomplex *x)
{
    npy_intp i, j;

    for (i = 0; i < n; i++)
        x[i] = b[i];
    for (i = 0; i < n; i++) {
        if (piv[i] != i) {
            dcomplex t = x[i];
            x[i] = x[piv[i]];
            x[piv[i]] = t;
        }
    }
    for (i = 1; i < n; i++) {
        dcomplex s = x[i];
        for (j = 0; j < i; j++)
            s -= M[i * n + j] * x[j];
        x[i] = s;
    }
    for (i = n - 1; i >= 0; i--) {
        dcomplex s = x[i];
        for (j = i + 1; j < n; j++)
            s -= M[i * n + j] * x[j];
        x[i] = s / M[i * n + i];
    }
}

static void
unit_vector(dcomplex *x, npy_intp n)
{
    double s = 1.0 / sqrt((double)n);
    npy_intp i;
    for (i = 0; i < n; i++)
        x[i] = s;
}

static double
vnormsq(const dcomplex *x, npy_intp n)
{
    double s = 0.0;
    npy_intp i;
    for (i = 0; i < n; i++) {
        double re = creal(x[i]), im = cimag(x[i]);
        s += re * re + im * im;
    }
    return s;
}

/* Eigenvector of the Hessenberg matrix for eigenvalue lam: inverse iteration
   with a slightly perturbed shift, then back through the reflectors. */
static void
eigenvector(const double *H, npy_intp n, dcomplex lam, const double *V,
            const double *beta, dcomplex *x, dcomplex *y)
{
    npy_intp i, j, k;
    double scale = cabs(lam), nrm, delta;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            scale += fabs(H[i * n + j]);
    if (scale == 0.0) {
        unit_vector(x, n);
        return;
    }
    delta = 1e-12 * scale;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g_LU[i * n + j] = H[i * n + j];
    for (i = 0; i < n; i++)
        g_LU[i * n + i] -= lam + delta;
    lu_factor(g_LU, n, g_piv);

    for (i = 0; i < n; i++)
        x[i] = 1.0;
    lu_solve(g_LU, n, g_piv, x, y);
    nrm = sqrt(vnormsq(y, n));
    if (nrm == 0.0 || !isfinite(nrm)) {
        unit_vector(x, n);
        return;
    }
    for (i = 0; i < n; i++)
        x[i] = y[i] / nrm;
    lu_solve(g_LU, n, g_piv, x, y);

    for (k = n - 3; k >= 0; k--) {          /* x <- Q y = P_1 ... P_{n-2} y */
        dcomplex s = 0.0;
        if (beta[k] == 0.0)
            continue;
        for (i = k + 1; i < n; i++)
            s += V[i * n + k] * y[i];
        s *= beta[k];
        for (i = k + 1; i < n; i++)
            y[i] -= s * V[i * n + k];
    }
    nrm = sqrt(vnormsq(y, n));
    if (nrm == 0.0 || !isfinite(nrm)) {
        unit_vector(x, n);
        return;
    }
    for (i = 0; i < n; i++)
        x[i] = y[i] / nrm;
}

/* ||A x - lam x|| / (max(||A||_1, 1) * ||x||) */
static double
residual(const double *a, npy_intp n, dcomplex lam, const dcomplex *x)
{
    double an = 0.0, rn = 0.0, xn = vnormsq(x, n);
    npy_intp i, j;

    for (i = 0; i < n; i++) {
        dcomplex s = 0.0;
        for (j = 0; j < n; j++)
            s += a[i * n + j] * x[j];
        s -= lam * x[i];
        rn += creal(s) * creal(s) + cimag(s) * cimag(s);
        for (j = 0; j < n; j++)
            an += fabs(a[i * n + j]);
    }
    an += cabs(lam);
    if (xn == 0.0)
        return 1e300;
    return sqrt(rn) / (sqrt(xn) * (an > 1.0 ? an : 1.0));
}

/* Returns 0 on success, -1 when the caller should fall back to LAPACK. */
static int
fast_eig(const double *a, npy_intp n, dcomplex *lam_out, dcomplex *x_out,
         int *all_real)
{
    npy_intp i, j, best;
    double bestm;
    dcomplex lam;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g_H[i * n + j] = a[i * n + j];

    hess_reduce(g_H, n, g_V, g_beta);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g_Hq[i * n + j] = g_H[i * n + j];

    if (qr_eigs(g_Hq, n) != 0)
        return -1;

    {
        double amax = 0.0;
        for (i = 0; i < n; i++) {
            double re = creal(g_Hq[i * n + i]), im = cimag(g_Hq[i * n + i]);
            double m = sqrt(re * re + im * im);
            if (m > amax) amax = m;
        }
        *all_real = 1;
        for (i = 0; i < n; i++) {
            dcomplex li = g_Hq[i * n + i];
            double lr = creal(li), lm = cimag(li);
            if (fabs(lm) > 1e-12 * (amax + sqrt(lr * lr + lm * lm))) {
                *all_real = 0;
                break;
            }
        }
    }

    /* largest magnitude; prefer the positive-imaginary member of a conjugate
       pair (LAPACK lists that one first, numpy's argmax picks it). */
    best = 0;
    bestm = -1.0;
    for (i = 0; i < n; i++) {
        double re = creal(g_Hq[i * n + i]), im = cimag(g_Hq[i * n + i]);
        double m = sqrt(re * re + im * im);
        if (m > bestm) bestm = m;
    }
    if (!isfinite(bestm))
        return -1;
    for (i = 0; i < n; i++) {
        dcomplex li = g_Hq[i * n + i];
        double lr = creal(li), lm = cimag(li);
        double br = creal(g_Hq[best * n + best]), bi = cimag(g_Hq[best * n + best]);
        if (sqrt(lr * lr + lm * lm) >= bestm - 1e-12 * (bestm > 1.0 ? bestm : 1.0)) {
            if (i == 0 || sqrt(br * br + bi * bi) <
                              bestm - 1e-12 * (bestm > 1.0 ? bestm : 1.0) ||
                lm > bi)
                best = i;
        }
    }
    lam = g_Hq[best * n + best];
    if (*all_real)
        lam = creal(lam);

    eigenvector(g_H, n, lam, g_V, g_beta, g_x, g_y);
    if (*all_real) {
        double nrm = 0.0;
        for (i = 0; i < n; i++) {
            g_x[i] = creal(g_x[i]);
            nrm += creal(g_x[i]) * creal(g_x[i]);
        }
        nrm = sqrt(nrm);
        if (nrm > 0.0)
            for (i = 0; i < n; i++)
                g_x[i] = creal(g_x[i]) / nrm;
    }
    if (residual(a, n, lam, g_x) > 1e-9)
        return -1;

    *lam_out = lam;
    for (i = 0; i < n; i++)
        x_out[i] = g_x[i];
    return 0;
}

/* ------------------------------------------------------------------- glue */

static PyObject *
py_setup(PyObject *self, PyObject *args)
{
    const char *path, *sym;
    void *h, *f;

    if (!PyArg_ParseTuple(args, "ss", &path, &sym))
        return NULL;
    if (alloc_buffers() != 0)
        return PyErr_NoMemory();
    h = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (h == NULL) {
        PyErr_SetString(PyExc_ImportError, dlerror());
        return NULL;
    }
    f = dlsym(h, sym);
    if (f == NULL) {
        PyErr_Format(PyExc_ImportError, "symbol %s not found in %s", sym, path);
        return NULL;
    }
    g_dgeev = (dgeev_fn)f;
    Py_RETURN_NONE;
}

static int
lapack_eig(const double *a, npy_intp n, double *wr, double *wi, double *vr)
{
    char jobvl = 'N', jobvr = 'V';
    npy_intp i, j, lda = n, ldvl = 1, ldvr = n, lwork = WORKLEN, info = 0, nn = n;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            g_a[j * n + i] = a[i * n + j];
    g_dgeev(&jobvl, &jobvr, &nn, g_a, &lda, wr, wi, NULL, &ldvl, vr, &ldvr,
            g_work, &lwork, &info, (size_t)1, (size_t)1);
    return info == 0 ? 0 : -1;
}

static PyObject *
build_result(npy_intp n, dcomplex lam, const dcomplex *x, int have_x,
             const double *wr, const double *wi, const double *vr, npy_intp best,
             int is_complex)
{
    PyArray_Descr *dt;
    PyObject *ev, *vec;
    double val[2];
    npy_intp i;

    vec = PyArray_SimpleNew(1, &n, is_complex ? NPY_COMPLEX128 : NPY_FLOAT64);
    if (vec == NULL)
        return NULL;

    if (have_x) {
        val[0] = creal(lam);
        val[1] = cimag(lam);
        if (is_complex) {
            double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
            for (i = 0; i < n; i++) {
                out[2 * i] = creal(x[i]);
                out[2 * i + 1] = cimag(x[i]);
            }
        }
        else {
            double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
            for (i = 0; i < n; i++)
                out[i] = creal(x[i]);
        }
    }
    else {
        val[0] = wr[best];
        val[1] = wi[best];
        if (wi[best] == 0.0) {
            double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
            const double *col = vr + best * n;
            for (i = 0; i < n; i++)
                out[i] = col[i];
        }
        else {
            double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
            const double *c0, *c1;
            double sg = (wi[best] > 0.0) ? 1.0 : -1.0;
            if (wi[best] > 0.0) { c0 = vr + best * n; c1 = c0 + n; }
            else { c0 = vr + (best - 1) * n; c1 = c0 + n; }
            for (i = 0; i < n; i++) {
                out[2 * i] = c0[i];
                out[2 * i + 1] = sg * c1[i];
            }
        }
    }

    dt = PyArray_DescrFromType(is_complex ? NPY_COMPLEX128 : NPY_FLOAT64);
    ev = PyArray_Scalar(val, dt, NULL);
    Py_DECREF(dt);
    if (ev == NULL) {
        Py_DECREF(vec);
        return NULL;
    }
    return Py_BuildValue("(NN)", ev, vec);
}

static int
check_array(PyObject *arg, npy_intp *np)
{
    PyArrayObject *arr;

    if (!PyArray_Check(arg) || PyArray_NDIM((PyArrayObject *)arg) != 2) {
        PyErr_SetString(PyExc_TypeError, "expected 2-D numpy array");
        return -1;
    }
    arr = (PyArrayObject *)arg;
    *np = PyArray_DIM(arr, 0);
    if (PyArray_DIM(arr, 1) != *np || *np < 1 || *np > MAXN ||
        PyArray_TYPE(arr) != NPY_FLOAT64 || !PyArray_IS_C_CONTIGUOUS(arr)) {
        PyErr_SetString(PyExc_TypeError, "unsupported array");
        return -1;
    }
    return 0;
}

